// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2020, "6-7", [{"author":"Е. Муравенко","question":"Фокстерьера Микки из книги Саши Чёрного мучает такой вопрос: «Почему Зинин дядя сказал, что у него „ … на лоб полезли“? Никуда они не полезли, я сам видел». Какое слово мы заменили многоточием?","choices":["волосы","усы","глаза","очки","уши"],"key":"В","review":["Что лезет на лоб","Фокстерьер понял слова дяди буквально и удивился, что никто никуда не лез. В речи так описывают сильное удивление человека.","«Глаза на лоб полезли» — устойчивое выражение. Оно значит, что человек изумился или широко раскрыл глаза."]},{"author":"И. Рубанов","question":"— Этими сырыми дровами нельзя топить печку. Положи их отдельно, пусть они ... .","choices":["засохнут","просохнут","присохнут","отсохнут","пересохнут"],"key":"Б","review":["Сырые дрова","Дровам нужно дать высохнуть после сырости. «Засохнуть» чаще говорят о растениях или о более длительном высыхании.","Когда из влажного материала уходит лишняя вода, он «просыхает». Поэтому пусть дрова просохнут."]},{"author":"П. Аркадьев","question":"Какое из данных слов в современном русском языке имеет ударение только на первом слоге?","choices":["договор","приговор","разговор","заговор","уговор"],"key":"Г","review":["Ударение в слове","В «договор», «приговор», «разговор» и «уговор» ударение в этих формах падает на последний слог: -во́р.","У слова «за́говор» ударным является первый слог. Ударение сохранилось в обоих значениях: тайный сговор и заклинание."]},{"author":"П. Аркадьев","question":"Какое слово лишнее?","choices":["длиннее","зеленее","раннее","сильнее","чудеснее"],"key":"В","review":["Форма сравнения","«Длиннее», «зеленее», «сильнее» и «чудеснее» сравнивают степень признака. По смыслу это «более длинный», «более зелёный» и так далее.","«Раннее» — форма среднего рода, например «раннее утро». Для сравнения по времени говорят «раньше»."]},{"author":"И. Рубанов","question":"1. Наши доходы составили в общей сложности рублей четыреста.\n2. В общей сложности ученики решили больше двадцати задач.\n3. Мы провели в Москве в общей сложности больше двух недель.\n4. Проблема не в отдельных трудностях, а в общей сложности предстоящей работы.\n5. Мальчики, собирая грибы, нашли их в общей сложности около сотни.\nВ каком из этих пяти предложений в общей сложности означает не то, что в остальных?","choices":["в первом","во втором","в третьем","в четвёртом","в пятом"],"key":"Г","review":["Значения слова «сложность»","В первом, втором, третьем и пятом примерах «в общей сложности» можно заменить словом «всего». Считается сумма денег, задач, недель или грибов.","В четвёртой фразе имеется в виду общий уровень трудности всей работы. Здесь «сложность» называет свойство работы."]},{"author":"Е. Бикмаев","question":"Заполните пропуск: Васенька _____ вёслами, языком и ногами и кричал, что задел веслом рыбу (Тэффи. Из дневников).","choices":["болтал","бултыхал","качал","теребил","трепал"],"key":"А","review":["Сразу три действия","Нужен глагол, с которым сочетаются вёсла, язык и ноги. Им можно описывать небрежное движение туда-сюда.","«Болтать вёслами» и «болтать ногами» относятся к движению. «Болтать языком» означает много говорить. Общий глагол — «болтал»."]},{"author":"О. Подлесская","question":"В стихотворении Романа Сефа читаем:\nМы встанем\nЧуть свет,\nЗа окошком\nТемно,\nЗвезда одинокая\nСмотрит в окно.\nМы снасти возьмём\nИ на цыпочках\nВыйдем,\nИ сразу\nБескрайнее\nНебо увидим…\nКуда идут герои?","choices":["на охоту","на рыбалку","за грибами","на стройку","в школу"],"key":"Б","review":["Снасти в стихотворении","Герои выходят на рассвете после того, как берут с собой снасти. Это специальные приспособления, связанные с их занятием.","«Снасти» — в том числе рыболовные принадлежности: удочки, лески и крючки. В стихотворении герои идут на рыбалку."]},{"author":"И. Рубанов","question":"Какое из этих слов можно понять в двух совершенно разных смыслах?","choices":["однотонный","полуторатонный","двухсполовинойтонный","пятидесятитонный","стотонный"],"key":"А","review":["Два разных «тона»","Большинство предложенных прилагательных содержит массу в тоннах. «Однотонный» тоже может означать «весящий одну тонну».","При этом «тон» — цветовой оттенок. Однотонная рубашка имеет один цвет. Только первое слово допускает оба разных смысла."]},{"author":"Е. Муравенко","question":"В какой паре слов второе образовано с помощью уменьшительно-ласкательного суффикса от первого?","choices":["пора — порка","ворона — воронка","родина — родинка","ложа — ложка","сторона — сторонка"],"key":"Д","review":["Уменьшительная форма","Уменьшительно-ласкательное слово сохраняет смысл исходного: маленькая сторона может называться «сторонка».","«Воронка» не маленькая ворона, «родинка» не маленькая родина, «порка» не разновидность поры, «ложка» не маленькая ложа. Подходит последняя пара."]},{"author":"А. Пиперски","question":"В западноевропейской традиции ноты часто обозначаются буквами: до — С, ре — D, ми — E, фа — F, соль — G, ля — A, си — B или H. Как называется произведение немецкого композитора Карла Готлиба Геринга (1766– 1853), которое начинается с нот до–ля–фа–фа–ми–ми?","choices":["Пивная симфония","Винная рапсодия","Чайная кантата","Кофейный канон","Молочная оратория"],"key":"Г","review":["Мелодия из букв","Подставим обозначения нот: до — C, ля — A, фа — F, фа — F, ми — E, ми — E.","Получается CAFFEE. Это старое написание немецкого слова «кофе», поэтому мелодия называется «Кофейный канон»."]},{"author":"С. Бурлак","question":"Какой из этих глаголов спрягается не так, как остальные?","choices":["застегни","заверни","зашвырни","затемни","засни"],"key":"Г","review":["Как меняются глаголы","Образуем формы «застегнёшь», «завернёшь», «зашвырнёшь», «заснёшь». В них после мягкой Н звучит Ё и есть окончание первого спряжения.","У «затемнить» будет «затемнишь» с И. Это второе спряжение, которое отличается от остальных."]},{"author":"Б. Иомдин","question":"周二　周四　周一　周三\nЧто здесь написано по-китайски?","choices":["понедельник, вторник, среда, четверг","вторник, четверг, понедельник, среда","среда, четверг, понедельник, вторник","четверг, вторник, понедельник, среда","вторник, понедельник, четверг, среда"],"key":"Б","review":["Дни недели по-китайски","У всех четырёх сочетаний общий знак 周, обозначающий неделю. Вторые знаки — числа: 一 один, 二 два, 三 три, 四 четыре.","В записи стоят числа 2, 4, 1, 3. Если понедельник первый, это вторник, четверг, понедельник, среда."]},{"author":"С. Волков","question":"Четыре слова образованы от глаголов одного вида, а одно — от глагола другого вида. Какое это слово?","choices":["проситель","носитель","спаситель","даритель","хулитель"],"key":"В","review":["Вид исходного глагола","«Проситель» связан с «просить», «носитель» с «носить», «даритель» с «дарить» и «хулитель» с «хулить». Все отвечают на «что делать?».","«Спаситель» образован от глагола совершенного вида «спасти», который отвечает на «что сделать?»."]},{"author":"Е. Бикмаев","question":"Даны латинские названия пяти видов клюквы (по устаревшей классификации): Oxycoccus erythrocarpus, Oxycoccus quadripetalus, Oxycoccus macrocarpus, Oxycoccus palustris, Oxycoccus microcarpus. Первое слово в названиях обозначает клюкву. Выберите вариант, где даны в правильном порядке переводы вторых слов.","choices":["красноплодная, четырёхлепестная, мелкоплодная, луговая, крупноплодная","красноплодная, четырёхлепестная, крупноплодная, болотная, мелкоплодная","красносортная, четырёхлепестная, крупноплодная, садовая, мелкоплодная","черносортная, пятилепестная, малоплодная, болотная, бесплодная","черноплодная, пятилепестная, мелкоплодная, луговая, крупноплодная"],"key":"Б","review":["Латинские названия клюквы","В quadripetalus видно quadri- «четыре» и часть со значением «лепесток». Макро- и микро- различают крупное и мелкое, а -carpus относится к плодам.","Эритро- обозначает красный цвет, palustris — болотное место. По порядку получаются красноплодная, четырёхлепестная, крупноплодная, болотная и мелкоплодная."]},{"author":"М. Рубинштейн","question":"Книга Анны Красильщик о школьниках называется ________.","choices":["«Половина»","«Три четверти»","«Одна вторая»","«Две трети»","«Три десятых»"],"key":"Б","review":["Название книги о классе","В школе четвертями называют части учебного года. Название книги числом четвертей подсказывает её школьную тему.","Книга Анны Красильщик называется «Три четверти». Среди вариантов это название дано под Б."]},{"author":"А. Сомин","question":"Даны белорусские слова и их переводы на русский язык: усюды ‘везде’, судзіць ‘судить’, гладзіць ‘гладить’. Как с белорусского языка переводится слово распаўсюдзіць? (Буква ў обозначает звук, средний между у и в, буквосочетание дз обозначает один звук.)","choices":["распорядиться","распрямить","распаковать","расположить","распространить"],"key":"Д","review":["Белорусский глагол","«Усюды» значит «везде». Похожая часть паўсюд- напоминает русское «повсюду». По словам судзіць и гладзіць видим, что -дзіць соответствует русскому -дить.","Распаўсюдзіць — сделать так, чтобы что-то распространилось повсюду. По-русски это «распространить»."]},{"author":"А. Панина","question":"Какое предложение значит не то, что остальные? Этот человек мне ... .","choices":["приятен","нравится","импонирует","симпатизирует","по душе"],"key":"Г","review":["Кому кто нравится","«Приятен мне», «нравится мне», «импонирует мне» и «мне по душе» описывают моё отношение к другому человеку.","«Симпатизирует мне» означает, что другой человек испытывает симпатию ко мне. Направление отношения изменилось."]},{"author":"О. Подлесская","question":"Найдите выражение, синонимичное выражению как ошпаренный.","choices":["как резаный","как в воду опущенный","как ужаленный","как убитый","как вкопанный"],"key":"В","review":["Резкая реакция","«Как ошпаренный» говорят о том, кто внезапно вскочил или помчался, будто почувствовал резкую боль.","Такую же реакцию передаёт «как ужаленный». «Как вкопанный» описывает неподвижность, а «как в воду опущенный» — подавленность."]},{"author":"Б. Иомдин","question":"Сколько разных гласных букв здесь пропущено: дав_шний, давн_шний, никуд_шный, тогд_шний, тут_шний? В каждом слове пропущена одна буква.","choices":["везде одна и та же","две","три","четыре","пять"],"key":"Д","review":["Гласные в пяти словах","Восстановим написание: «давешний», «давнишний», «никудышный», «тогдашний», «тутошний».","На местах пропусков стоят Е, И, Ы, А и О. Все пять гласных различаются."]},{"author":"А. Панина","question":"У какого из этих слов больше суффиксов, чем у остальных?","choices":["спиральный","стиральный","свекольный","стекольный","сольный"],"key":"Б","review":["Суффиксы в прилагательных","«Спиральный», «свекольный», «стекольный» и «сольный» соотносятся с существительными «спираль», «свёкла», «стекло», «соль». Согласная Л относится к основе.","«Стиральный» связано с глаголом «стирать». К его основе с -а- добавлены части, образующие прилагательное. Здесь суффиксов больше."]},{"author":"С. Сай","question":"Какое слово не связано с остальными по происхождению?","choices":["выдворять","дворняжка","подворотня","подворье","придворный"],"key":"В","review":["Ворота или двор","«Выдворять», «дворняжка», «подворье» и «придворный» исторически связаны со словом «двор».","«Подворотня» обозначает пространство под воротами. Она связана с «воротами», поэтому её происхождение отличается."]},{"author":"Е. Муравенко","question":"Даны пары глаголов, различающихся в 1-м лице единственного числа только ударением: 1) сто́ю — стою́, 2) та́ю — таю́, 3) па́рю — парю́, 4) узна́ю — узнаю́. Образуем теперь от каждого глагола форму 3-го лица множественного числа. В какой паре формы будут различаться не только ударением?","choices":["в первой","во второй","в третьей","в четвёртой","во всех парах формы глаголов различаются только ударением"],"key":"Б","review":["Формы «они»","В первых лицах «та́ю» и «таю́» одинаково пишутся, хотя первое происходит от «таять», а второе — от «таить».","В третьем лице множества получаются «та́ют» и «тая́т». В отличие от остальных пар, здесь меняется и гласная буква окончания."]},{"author":"О. Подлесская","question":"Определить, сказать, обстоять, подлежать. Каким глаголом можно продолжить этот список?","choices":["замечать","уточнить","дополнить","возразить","объявить"],"key":"В","review":["Члены предложения","От «определить» получается «определение», от «сказать» — «сказуемое», от «обстоять» — «обстоятельство», от «подлежать» — «подлежащее».","Все эти слова называют члены предложения. Такой же грамматический термин «дополнение» связан с глаголом «дополнить»."]},{"author":"И. Рубанов","question":"Упав в ..., легко ... . Многоточиями в этом утверждении заменены одинаковые по написанию слова, начинающиеся на ... .","choices":["ор-","пр-","ру-","су-","ту-"],"key":"Б","review":["Одинаковые буквы","Первый пропуск называет место, куда можно упасть. Второй пропуск называет то, что после этого может случиться.","«Упав в про́пасть, легко пропа́сть». Слова различаются ударением, но пишутся одинаково и начинаются на ПР."]},{"author":"Е. Бикмаев","question":"В романе Евгения Фёдорова «Каменный пояс» рассказывается о старинной заводской работе по выжиганию леса для заготовки угля: «Работа эта неприглядна и тяжела: валили лес, распиливали его, подвозили, складывали в поленницы, потом в кучи, дерновали и жгли». Хотя вы могли не слышать это слово раньше, назовите человека, который этим занимался.","choices":["углежог","углежёг","углежиг","углежег","углижог"],"key":"А","review":["Название работника","Работник выжигал древесный уголь. Название профессии нужно сложить из частей, связанных с «уголь» и «жечь».","Существительное «ожог» подсказывает написание -жог. Соединяем угл- и -жог- через Е, получается «углежог»."]},{"author":"О. Подлесская","question":"Но гномы единодушно ... за ужин, притом не откладывая, и потому не пожелали задерживаться (Д. Р. Р. Толкин, «Хоббит», перевод Н. Рахмановой).","choices":["сидели","стояли","висели","лежали","бежали"],"key":"Б","review":["Что решили гномы","Гномы уже приняли решение поужинать без промедления. Им важно было высказать поддержку этому решению.","«Стоять за» означает выступать в пользу чего-либо. В цитате гномы «стояли за ужин»."]},{"author":"Б. Иомдин","question":"Даны названия нескольких мостов в Санкт-Петербурге и история их происхождения. Какое название образовано не так, как остальные?","choices":["Аничков мост — в честь инженера Михаила Аничкова","Бердов мост — в честь инженера Карла Берда","Матвеев мост — в честь рабочего Михаила Матвеева","Поцелуев мост — в честь купца Никифора Поцелуева","Тучков мост — в честь купца Авраама Тучкова"],"key":"Б","review":["Фамилии и мосты","Фамилии Аничков, Матвеев, Поцелуев и Тучков уже имеют ту же форму, что и названия мостов.","Фамилия Карла — Берд. Для названия «Бердов мост» к ней добавили -ов. Так образовано только одно название."]},{"author":"Б. Иомдин","question":"Четыре фразы иногда используются на конкурсе «Угадай изменённую фразу», а пятая — нет. Какая?","choices":["От глупого писка до беды близко.","На горе и шапка горит.","Врач на горе — весна во дворе.","По одёжке протягивай ложки.","Без труда не вынешь и рыбку из пруда"],"key":"Д","review":["Неизменённая пословица","«На горе и шапка горит» напоминает «На воре и шапка горит». «По одёжке протягивай ложки» переделывает окончание «протягивай ножки».","«Без труда не вынешь и рыбку из пруда» уже совпадает с известной пословицей. Угадывать исходную форму здесь не нужно."]},{"author":"Б. Иомдин","question":"Мы отсеяли всё ненужное. В этой фразе можно поменять одну букву на другую, и смысл почти не изменится. На какую?","choices":["б","и","к","н","я"],"key":"В","review":["Замена одной буквы","«Отсеяли» здесь значит «удалили ненужное». Ищем глагол, который отличается одной буквой, но сохраняет общий смысл.","Если заменить Я на К, получится «отсекли». Фраза «мы отсекли всё ненужное» передаёт близкую мысль."]},{"author":"А. Пиперски","question":"В какой паре слова ни в какой форме не рифмуются друг с другом?","choices":["рука — мешок","нога — враг","спина — картина","губа — палуба","стопа — трущоба"],"key":"Г","review":["Рифмы в разных формах","Подбираем формы с одинаковым звучанием после ударной гласной: «рука́ми — мешка́ми», «нога́ — врага́», «спи́ны — карти́ны», «стоп — трущоб» с оглушённой Б.","У «палуба» ударение остаётся на первом слоге. У форм «губа» нет такого окончания после ударной гласной, и эти слова не рифмуются."]}], {"year":2020,"grade":"6-7","tasksFile":"6-7.pdf","answersFile":"6-7-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2020-1.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
